## Как это устроено

- Экраны работают только с «хранилищем цитат». Слова SwiftData в экранах нет. При переходе на GRDB пишется ещё одна реализация того же хранилища, а экраны не меняются.
- Хранилище умеет три вещи: показывать цитаты книги (новые сверху), добавлять цитату и удалять её.
- Список цитат обновляется сам. Если цитату добавили или удалили на другом экране, открытый список это увидит. Раньше экраны получали это от SwiftData автоматически, поэтому такое обновление заложено сразу: иначе при переходе на GRDB пришлось бы переделывать каждый экран.
- Порядок цитат задан в одном месте. Если две цитаты созданы в один и тот же момент, порядок между ними всё равно постоянный, при любом способе хранения.
- Тесты проверяют поведение, а не устройство кода. Тот же набор потом проверит и вариант на GRDB.
- Код проверил отдельный рецензент, в два раунда. Всё, что он посчитал обязательным, исправлено.

### `BookQuote.swift`
```swift
import Foundation

/// A quote as screens see it: a plain value that does not depend on the storage engine.
nonisolated struct BookQuote: Identifiable, Hashable, Sendable {
    let id: UUID
    let text: String
    let bookID: UUID
    let createdAt: Date

    /// The order screens show quotes in: newest first. Quotes created at the same moment are
    /// ordered by id, so every storage implementation returns the same list.
    static func newestFirst(_ lhs: BookQuote, _ rhs: BookQuote) -> Bool {
        if lhs.createdAt != rhs.createdAt {
            return lhs.createdAt > rhs.createdAt
        }
        return lhs.id.uuidString > rhs.id.uuidString
    }
}
```

### `QuoteStore.swift`
```swift
import Foundation

/// The only way screens read and change quotes. Screens never import the storage engine,
/// so replacing SwiftData means writing another conforming type, not touching screens.
@MainActor
protocol QuoteStore: AnyObject, Sendable {
    /// The book's quotes in `BookQuote.newestFirst` order: the current list right away, then a new
    /// list after every change made through this store. Ends with an error if reading fails;
    /// ends when the caller stops iterating (for example, when the screen's `.task` is cancelled).
    func quoteUpdates(forBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error>

    /// Saves a new quote with the text exactly as given and returns it as stored.
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote

    /// Deletes the quote. Deleting a quote that no longer exists is not an error.
    func deleteQuote(id: UUID) async throws
}
```

### `SwiftDataQuoteStore.swift`
```swift
import Foundation
import SwiftData

/// `QuoteStore` over SwiftData. Create one per app and share it: updates reach only the
/// subscribers of the instance that made the change.
@MainActor
final class SwiftDataQuoteStore: QuoteStore {
    private typealias Updates = AsyncThrowingStream<[BookQuote], any Error>

    private struct Subscriber {
        let bookID: UUID
        let continuation: Updates.Continuation
    }

    private let modelContainer: ModelContainer
    // Private to this store, so rolling back after a failed save never discards anyone else's edits.
    private let context: ModelContext
    private let now: @MainActor () -> Date
    private var subscribers: [UUID: Subscriber] = [:]

    init(modelContainer: ModelContainer, now: @escaping @MainActor () -> Date = { .now }) {
        self.modelContainer = modelContainer
        self.context = ModelContext(modelContainer)
        self.context.autosaveEnabled = false
        self.now = now
    }

    func quoteUpdates(forBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        // Only the latest list matters to a screen, so older unread lists are dropped.
        let (stream, continuation) = Updates.makeStream(bufferingPolicy: .bufferingNewest(1))
        let subscriberID = UUID()
        subscribers[subscriberID] = Subscriber(bookID: bookID, continuation: continuation)
        continuation.onTermination = { [weak self] _ in
            Task { @MainActor in self?.subscribers[subscriberID] = nil }
        }
        publish(to: subscriberID)
        return stream
    }

    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let model = Quote(id: UUID(), text: text, bookID: bookID, createdAt: now())
        context.insert(model)
        try saveOrRollback()
        publishToAll()
        return BookQuote(model)
    }

    func deleteQuote(id: UUID) async throws {
        let models = try context.fetch(FetchDescriptor<Quote>(predicate: #Predicate { $0.id == id }))
        guard !models.isEmpty else { return }
        for model in models {
            context.delete(model)
        }
        try saveOrRollback()
        publishToAll()
    }

    private func fetchQuotes(forBook bookID: UUID) throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.bookID == bookID })
        return try context.fetch(descriptor).map { BookQuote($0) }.sorted(by: BookQuote.newestFirst)
    }

    private func saveOrRollback() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }

    private func publish(to subscriberID: UUID) {
        guard let subscriber = subscribers[subscriberID] else { return }
        do {
            subscriber.continuation.yield(try fetchQuotes(forBook: subscriber.bookID))
        } catch {
            subscriber.continuation.finish(throwing: error)
            subscribers[subscriberID] = nil
        }
    }

    private func publishToAll() {
        for subscriberID in Array(subscribers.keys) {
            publish(to: subscriberID)
        }
    }
}

private extension BookQuote {
    // Explicitly main-actor: under main-actor default isolation the `Quote` model's properties are main-actor-isolated.
    @MainActor
    init(_ model: Quote) {
        self.init(id: model.id, text: model.text, bookID: model.bookID, createdAt: model.createdAt)
    }
}
```

