@testable import Slumpy

/// The behavior screens rely on. Written against `any QuoteStore` so a future storage
/// implementation runs the same checks through its own `makeStore`.
@MainActor
@Suite(.timeLimit(.minutes(1)))
struct SwiftDataQuoteStoreTests {
    private let bookID = UUID()
    private let otherBookID = UUID()

    @Test func listsNewestFirstByCreationTime() async throws {
        // Creation times differ from insertion order, so "reverse insertion order" would fail.
        let store = try makeStore(clock: TestClock(moment(4), moment(1), moment(6), moment(2), moment(5), moment(3)))
        let a = try await store.addQuote(text: "A", toBook: bookID)
        let b = try await store.addQuote(text: "B", toBook: bookID)
        let c = try await store.addQuote(text: "C", toBook: bookID)
        let d = try await store.addQuote(text: "D", toBook: bookID)
        let e = try await store.addQuote(text: "E", toBook: bookID)
        let f = try await store.addQuote(text: "F", toBook: bookID)

        #expect(try await currentQuotes(store, book: bookID) == [c, e, a, f, d, b])
    }

    @Test func quotesFromTheSameMomentKeepAStableOrder() async throws {
        let store = try makeStore(clock: TestClock(moment(1)))
        var added: [BookQuote] = []
        for index in 0..<10 {
            added.append(try await store.addQuote(text: "\(index)", toBook: bookID))
        }

        let expected = added.map(\.id).sorted { $0.uuidString > $1.uuidString }
        #expect(try await currentQuotes(store, book: bookID).map(\.id) == expected)
    }

    @Test func listsOnlyTheRequestedBook() async throws {
        let store = try makeStore()
        let mine = try await store.addQuote(text: "Mine", toBook: bookID)
        _ = try await store.addQuote(text: "Other", toBook: otherBookID)

        #expect(try await currentQuotes(store, book: bookID) == [mine])
    }

    @Test func addedQuoteReadsBackUnchanged() async throws {
        let text = "  «Первая строка»\nвторая строка 📖  "
        let store = try makeStore(clock: TestClock(moment(5)))
        let added = try await store.addQuote(text: text, toBook: bookID)

        #expect(added.text == text)
        #expect(added.bookID == bookID)
        #expect(added.createdAt == moment(5))
        #expect(try await currentQuotes(store, book: bookID) == [added])
    }

    @Test func openListSeesAddAndDelete() async throws {
        let store = try makeStore()
        var updates = store.quoteUpdates(forBook: bookID).makeAsyncIterator()
        #expect(try await updates.next(isolation: #isolation) == [])

        let quote = try await store.addQuote(text: "A", toBook: bookID)
        #expect(try await updates.next(isolation: #isolation) == [quote])

        try await store.deleteQuote(id: quote.id)
        #expect(try await updates.next(isolation: #isolation) == [])
    }

    @Test func deleteRemovesOnlyThatQuote() async throws {
        let store = try makeStore(clock: TestClock(moment(1), moment(2)))
        let kept = try await store.addQuote(text: "Kept", toBook: bookID)
        let removed = try await store.addQuote(text: "Removed", toBook: bookID)

        try await store.deleteQuote(id: removed.id)

        #expect(try await currentQuotes(store, book: bookID) == [kept])
    }

    @Test func deletingAMissingQuoteChangesNothing() async throws {
        let store = try makeStore()
        let kept = try await store.addQuote(text: "Kept", toBook: bookID)

        try await store.deleteQuote(id: UUID())

        #expect(try await currentQuotes(store, book: bookID) == [kept])
    }

    @Test func changesAreSavedNotJustKeptInMemory() async throws {
        let container = try makeContainer()
        let writer = try makeStore(container: container, clock: TestClock(moment(1), moment(2)))
        let removed = try await writer.addQuote(text: "Removed", toBook: bookID)
        let kept = try await writer.addQuote(text: "Kept", toBook: bookID)

        // A fresh store has its own context, so it only sees what the writer saved.
        let readerAfterAdd = try makeStore(container: container)
        #expect(try await currentQuotes(readerAfterAdd, book: bookID) == [kept, removed])

        try await writer.deleteQuote(id: removed.id)

        let readerAfterDelete = try makeStore(container: container)
        #expect(try await currentQuotes(readerAfterDelete, book: bookID) == [kept])
    }

    private func makeContainer() throws -> ModelContainer {
        try ModelContainer(for: Quote.self, configurations: ModelConfiguration(isStoredInMemoryOnly: true))
    }

    private func makeStore(
        container: ModelContainer? = nil,
        clock: TestClock = TestClock(moment(0))
    ) throws -> any QuoteStore {
        SwiftDataQuoteStore(modelContainer: try container ?? makeContainer(), now: { clock.next() })
    }

    private func currentQuotes(_ store: any QuoteStore, book: UUID) async throws -> [BookQuote] {
        var updates = store.quoteUpdates(forBook: book).makeAsyncIterator()
        return try #require(try await updates.next(isolation: #isolation))
    }
}

/// Returns the given moments in order, then keeps returning the last one.
@MainActor
private final class TestClock {
    private var moments: [Date]

    init(_ moments: Date...) {
        self.moments = moments
    }

    func next() -> Date {
        moments.count > 1 ? moments.removeFirst() : moments[0]
    }
}

private func moment(_ seconds: TimeInterval) -> Date {
    Date(timeIntervalSinceReferenceDate: 800_000_000 + seconds)
}
```

