## Код

**1. `QuoteStore.swift`** — в общий пакет с логикой (не импортирует ни SwiftData, ни SwiftUI)

```swift
import Foundation

/// A quote saved from a book, as screens see it. A plain value that does not
/// depend on how quotes are stored.
public nonisolated struct BookQuote: Identifiable, Hashable, Sendable {
    public let id: UUID
    public let text: String
    public let bookID: UUID
    public let createdAt: Date

    public init(id: UUID, text: String, bookID: UUID, createdAt: Date) {
        self.id = id
        self.text = text
        self.bookID = bookID
        self.createdAt = createdAt
    }

    /// The order quotes are listed in: newest first. Quotes created at the same
    /// moment are ordered by id, so every store returns the same order.
    public static func isListedBefore(_ a: BookQuote, _ b: BookQuote) -> Bool {
        if a.createdAt != b.createdAt {
            return a.createdAt > b.createdAt
        }
        return a.id.uuidString < b.id.uuidString
    }
}

/// Storage for quotes. Screens depend only on this protocol, so the backing
/// store (SwiftData today) can be replaced without touching them.
///
/// - Screens ignore `CancellationError` (a read throws it when the calling
///   task is cancelled, e.g. the screen disappeared); every other error is
///   opaque: show a generic failure, do not inspect the type.
/// - If a write throws, nothing was changed, so retrying cannot duplicate.
public nonisolated protocol QuoteStore: Sendable {
    /// Quotes of one book, ordered by `BookQuote.isListedBefore` (newest first).
    func quotes(forBook bookID: UUID) async throws -> [BookQuote]

    /// Saves a new quote for the book and returns it. The store assigns the id
    /// and the creation date; every call creates a new quote.
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote

    /// Deletes the quote. Deleting a quote that does not exist is not an error.
    func deleteQuote(id: UUID) async throws
}
```

**2. `InMemoryQuoteStore.swift`** — туда же, в пакет с логикой

```swift
import Foundation

/// Keeps quotes in memory only. For SwiftUI previews and screen tests.
public actor InMemoryQuoteStore: QuoteStore {
    private var storage: [UUID: BookQuote]
    private let now: @Sendable () -> Date

    public init(quotes: [BookQuote] = [], now: @escaping @Sendable () -> Date = { .now }) {
        self.storage = Dictionary(quotes.map { ($0.id, $0) }, uniquingKeysWith: { _, last in last })
        self.now = now
    }

    public func quotes(forBook bookID: UUID) -> [BookQuote] {
        storage.values
            .filter { $0.bookID == bookID }
            .sorted(by: BookQuote.isListedBefore)
    }

    public func addQuote(text: String, toBook bookID: UUID) -> BookQuote {
        let quote = BookQuote(id: UUID(), text: text, bookID: bookID, createdAt: now())
        storage[quote.id] = quote
        return quote
    }

    public func deleteQuote(id: UUID) {
        storage[id] = nil
    }
}
```

**3. `SwiftDataQuoteStore.swift`** — в таргет приложения, рядом с моделью `Quote`

```swift
import Foundation
import SwiftData

/// QuoteStore backed by SwiftData.
///
/// Runs on the main actor: each call touches one book's quotes, which is
/// cheap, and it keeps the non-Sendable ModelContext on one known thread
/// whatever the module's default isolation is.
@MainActor
final class SwiftDataQuoteStore: QuoteStore {
    private let container: ModelContainer
    private let now: @Sendable () -> Date

    init(container: ModelContainer, now: @escaping @Sendable () -> Date = { .now }) {
        self.container = container
        self.now = now
    }

    func quotes(forBook bookID: UUID) async throws -> [BookQuote] {
        let context = makeContext()
        let models = try context.fetch(FetchDescriptor<Quote>(predicate: #Predicate { $0.bookID == bookID }))
        // Models must not be read after the context that fetched them is released.
        return withExtendedLifetime(context) {
            models.map(value(of:)).sorted(by: BookQuote.isListedBefore)
        }
    }

    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let added = BookQuote(id: UUID(), text: text, bookID: bookID, createdAt: now())
        let context = makeContext()
        context.insert(Quote(id: added.id, text: added.text, bookID: added.bookID, createdAt: added.createdAt))
        try context.save()
        return added
    }

    func deleteQuote(id: UUID) async throws {
        let context = makeContext()
        let matching = try context.fetch(FetchDescriptor<Quote>(predicate: #Predicate { $0.id == id }))
        guard !matching.isEmpty else { return }
        for quote in matching {
            context.delete(quote)
        }
        try context.save()
    }

    /// A new context per call with autosave off: if `save()` throws, the
    /// context and its unsaved changes are dropped, so a failed write is never
    /// applied later and other screens' unsaved changes are not touched.
    private func makeContext() -> ModelContext {
        let context = ModelContext(container)
        context.autosaveEnabled = false
        return context
    }

    private func value(of quote: Quote) -> BookQuote {
        BookQuote(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

