import Foundation
import SwiftData
import Synchronization
import Testing
@testable import Slumpy        // app module: use the real name
import SlumpyKit               // logic package: use the real name

/// The contract every QuoteStore keeps. A future store (e.g. GRDB) is added to
/// `StoreKind` and must pass the same tests.
@MainActor
@Suite struct QuoteStoreContractTests {
    nonisolated enum StoreKind: CaseIterable, Sendable {
        case swiftData, inMemory
    }

    func makeStore(_ kind: StoreKind, clock: TestClock) throws -> any QuoteStore {
        let now: @Sendable () -> Date = { clock.now() }
        switch kind {
        case .swiftData:
            let container = try ModelContainer(
                for: Quote.self,
                configurations: ModelConfiguration(isStoredInMemoryOnly: true)
            )
            return SwiftDataQuoteStore(container: container, now: now)
        case .inMemory:
            return InMemoryQuoteStore(now: now)
        }
    }

    @Test(arguments: StoreKind.allCases)
    func listsOnlyThatBookNewestFirst(kind: StoreKind) async throws {
        // Dates match neither the order of adding, nor its reverse, nor oldest
        // first; the other book's quote is the newest of all.
        let store = try makeStore(kind, clock: TestClock(200, 400, 300, 100))
        let book = UUID()

        let a1 = try await store.addQuote(text: "a1", toBook: book)
        _ = try await store.addQuote(text: "other book", toBook: UUID())
        let a2 = try await store.addQuote(text: "a2", toBook: book)
        let a3 = try await store.addQuote(text: "a3", toBook: book)

        #expect(try await store.quotes(forBook: book) == [a2, a1, a3])
    }

    @Test(arguments: StoreKind.allCases)
    func quotesFromTheSameMomentHaveAStableOrder(kind: StoreKind) async throws {
