/// Returns the given dates (seconds since the reference date) one per call.
nonisolated final class TestClock: Sendable {
    private let dates: Mutex<[Date]>

    init(_ seconds: TimeInterval...) {
        dates = Mutex(seconds.map(Date.init(timeIntervalSinceReferenceDate:)))
    }

    func now() -> Date {
        dates.withLock { $0.removeFirst() }
    }
