### `CoverStore.swift`

```swift
import Foundation
import Synchronization
import UIKit

/// Book cover photos as JPEG files outside SwiftData, in two sizes.
///
/// Every saved photo gets a new ID and its files are never overwritten, so an image cached
/// under an ID is always the right one. `Book.coverID` points to the current photo.
/// Invariants the orphan sweep relies on: cover IDs come only from `save` in this process,
/// no two books share a cover ID, and only the app target reads these files.
nonisolated final class CoverStore: @unchecked Sendable {
    // @unchecked Sendable: all stored properties are `let`. NSCache is documented as
    // thread-safe, Mutex is Sendable, and files are touched only through FileManager.default,
    // which is safe to use from any thread for these operations.

    nonisolated enum Variant: String, CaseIterable, Sendable {
        /// Book screen: 160 × 240 pt at 3x, with headroom.
        case full
        /// Library list: up to 100 pt tall at 3x.
        case thumbnail

        var maxPixelLength: CGFloat {
            switch self {
            case .full: 1200
            case .thumbnail: 300
            }
        }
    }

    nonisolated enum StoreError: Error {
        case encodingFailed
    }

    static let shared = CoverStore(
        directory: .applicationSupportDirectory.appending(path: "Covers", directoryHint: .isDirectory)
    )

    private let directory: URL
    private let cache = NSCache<NSString, UIImage>()
    /// Photos saved by this process. The orphan sweep keeps them: a photo that was just written
    /// may not be in the database yet.
    private let savedThisSession = Mutex<Set<UUID>>([])

    init(directory: URL) {
        self.directory = directory
        cache.totalCostLimit = 50 * 1024 * 1024
    }

    /// The image if it is already in memory; cheap enough to call from a view's body.
    func cachedImage(for id: UUID, variant: Variant) -> UIImage? {
        cache.object(forKey: cacheKey(id, variant))
    }

    /// The image from memory or disk, decoded off the main thread; nil when the file is missing.
    @concurrent
    func image(for id: UUID, variant: Variant) async -> UIImage? {
        if let cached = cachedImage(for: id, variant: variant) { return cached }
        // A row that scrolled away no longer needs its cover: skip the read and the decode.
        guard !Task.isCancelled else { return nil }
        guard let stored = UIImage(contentsOfFile: fileURL(id, variant).path(percentEncoded: false)) else {
            return nil
        }
        // Decode now; otherwise the JPEG is decoded on the main thread while scrolling.
        let decoded = stored.preparingForDisplay() ?? stored
        remember(decoded, id, variant)
        return decoded
    }

    /// Downscales the photo, writes both variants, and returns the new cover ID.
    @concurrent
    func save(_ photo: UIImage) async throws -> UUID {
        let id = UUID()
        // Register before writing any file: removeOrphans relies on this order.
        savedThisSession.withLock { _ = $0.insert(id) }
        let full = Self.downscaled(photo, maxPixelLength: Variant.full.maxPixelLength)
        let thumbnail = Self.downscaled(full, maxPixelLength: Variant.thumbnail.maxPixelLength)
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            for (variant, image) in [(Variant.full, full), (Variant.thumbnail, thumbnail)] {
                guard let data = image.jpegData(compressionQuality: 0.8) else {
                    throw StoreError.encodingFailed
                }
                try data.write(to: fileURL(id, variant), options: .atomic)
            }
        } catch {
            removeFiles(of: id)
            throw error
        }
        remember(full, id, .full)
        remember(thumbnail, id, .thumbnail)
        return id
    }

    @concurrent
    func delete(_ id: UUID) async {
        removeFiles(of: id)
    }

    /// Deletes cover files that no book refers to: left after a book was deleted, or by a save
    /// that crashed before the database was updated.
    @concurrent
    func removeOrphans(referencedIDs: Set<UUID>) async {
        let fileManager = FileManager.default
        guard let files = try? fileManager.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil) else {
            return
        }
        // Read the session set only after listing: save registers an ID before writing its
        // files, so every listed file from this session is already in the set.
        let keep = referencedIDs.union(savedThisSession.withLock { $0 })
        for file in files {
            guard let id = Self.coverID(inFileName: file.lastPathComponent), !keep.contains(id) else { continue }
            try? fileManager.removeItem(at: file)
        }
    }

    // MARK: - Private

    private func removeFiles(of id: UUID) {
        for variant in Variant.allCases {
            cache.removeObject(forKey: cacheKey(id, variant))
            try? FileManager.default.removeItem(at: fileURL(id, variant))
        }
    }

    private func remember(_ image: UIImage, _ id: UUID, _ variant: Variant) {
        let bytes = Int(image.size.width * image.scale * image.size.height * image.scale) * 4
        cache.setObject(image, forKey: cacheKey(id, variant), cost: bytes)
    }

    private func fileURL(_ id: UUID, _ variant: Variant) -> URL {
        directory.appending(path: "\(id.uuidString).\(variant.rawValue).jpg", directoryHint: .notDirectory)
    }

    private func cacheKey(_ id: UUID, _ variant: Variant) -> NSString {
        "\(id.uuidString).\(variant.rawValue)" as NSString
    }

    /// Files that are not named `<UUID>.<variant>.jpg` are not ours and are never deleted.
    private static func coverID(inFileName name: String) -> UUID? {
        name.split(separator: ".").first.flatMap { UUID(uuidString: String($0)) }
    }

    /// `size` already accounts for the photo's orientation and drawing applies it, so the result
    /// is upright: camera photos come as landscape pixels with a rotation flag.
    private static func downscaled(_ image: UIImage, maxPixelLength: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let factor = min(1, maxPixelLength / max(pixelWidth, pixelHeight))
        let target = CGSize(width: (pixelWidth * factor).rounded(), height: (pixelHeight * factor).rounded())
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }
}
```

### `BookCoverEditing.swift`

```swift
import SwiftData
import UIKit

/// Sets and removes a book's cover. If the database save fails, the book keeps its previous
/// cover and the new photo is deleted.
@MainActor
enum BookCoverEditing {
    /// - Parameter save: commits the book; the app passes `modelContext.save`.
    static func setCover(_ photo: UIImage, on book: Book, store: CoverStore, save: () throws -> Void) async throws {
        let newID = try await store.save(photo)
        // The book may have been deleted while the photo was being saved.
        guard book.modelContext != nil, !book.isDeleted else {
            await store.delete(newID)
            return
        }
        let oldID = book.coverID
        book.coverID = newID
        do {
            try save()
        } catch {
            book.coverID = oldID
            await store.delete(newID)
            throw error
        }
        // Only now: until the book points to the new photo, the old one must stay.
        if let oldID { await store.delete(oldID) }
    }

    static func removeCover(from book: Book, store: CoverStore, save: () throws -> Void) async throws {
        guard let oldID = book.coverID else { return }
        book.coverID = nil
        do {
            try save()
        } catch {
            book.coverID = oldID
            throw error
        }
        await store.delete(oldID)
    }
}
