import SwiftUI

/// A book cover filling the frame the parent gives it (2:3), or a placeholder.
/// Decorative for VoiceOver: the title next to it says which book it is.
struct BookCoverView: View {
    let coverID: UUID?
    let variant: CoverStore.Variant

    @Environment(\.coverStore) private var coverStore
    /// The last load, tagged with its ID so a late result for a previous cover is ignored.
    @State private var loaded: (id: UUID, image: UIImage?)?

    var body: some View {
        Rectangle()
            .fill(Color(.secondarySystemFill))
            .overlay {
                switch displayed {
                case .image(let image):
                    Image(uiImage: image).resizable().scaledToFill()
                case .loading:
                    EmptyView()
                case .placeholder:
                    Image(systemName: "book.closed")
                        .imageScale(.large)
                        .foregroundStyle(.secondary)
                }
            }
            .clipShape(.rect(cornerRadius: 4))
            .accessibilityHidden(true)
            .task(id: coverID) {
                guard let coverID else { return }
                let image = await coverStore.image(for: coverID, variant: variant)
                guard !Task.isCancelled else { return }
                loaded = (coverID, image)
            }
    }

    private enum Displayed {
        case image(UIImage), loading, placeholder
    }

    private var displayed: Displayed {
        guard let coverID else { return .placeholder }
        // The memory cache first, so a row scrolled back into view shows its cover at once.
        if let cached = coverStore.cachedImage(for: coverID, variant: variant) { return .image(cached) }
        guard let loaded, loaded.id == coverID else { return .loading }
        return loaded.image.map(Displayed.image) ?? .placeholder
    }
}

extension EnvironmentValues {
    @Entry var coverStore: CoverStore = .shared
}
