    @State private var isCameraPresented = false
    @State private var isSaving = false
    @State private var isConfirmingRemoval = false
    @State private var problem: Problem?

    var body: some View {
        VStack(spacing: 12) {
            BookCoverView(coverID: book.coverID, variant: .full)
                .frame(width: 160, height: 240)
                .overlay {
                    if isSaving {
                        ProgressView()
                            .padding()
                            .background(.regularMaterial, in: .rect(cornerRadius: 8))
                    }
                }
            if book.coverID == nil {
                Button("Сфотографировать обложку", systemImage: "camera") {
                    Task { await openCamera() }
                }
            } else {
                Menu("Изменить обложку", systemImage: "camera") {
                    Button("Переснять", systemImage: "camera") {
                        Task { await openCamera() }
                    }
                    Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                        isConfirmingRemoval = true
                    }
                }
            }
        }
        // Inside a List row each button must take only its own taps.
        .buttonStyle(.bordered)
        .disabled(isSaving)
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker { photo in
                isCameraPresented = false
                if let photo {
                    Task { await setCover(photo) }
                }
            }
            .ignoresSafeArea()
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isConfirmingRemoval, titleVisibility: .visible) {
            Button("Удалить", role: .destructive) {
                Task { await removeCover() }
            }
        }
        .alert(Text(problem?.title ?? ""), isPresented: isShowingProblem, presenting: problem) { problem in
            if problem == .cameraDenied {
                Button("Открыть Настройки") {
                    if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
                }
                Button("Отмена", role: .cancel) {}
            }
        } message: { problem in
            Text(problem.message)
        }
    }

    private var isShowingProblem: Binding<Bool> {
        Binding(get: { problem != nil }, set: { if !$0 { problem = nil } })
    }

    private func openCamera() async {
        guard UIImagePickerController.isSourceTypeAvailable(.camera) else {
            problem = .cameraUnavailable
            return
        }
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            isCameraPresented = true
        case .notDetermined:
            // The user has just answered the system prompt; a "no" needs no extra alert.
            isCameraPresented = await AVCaptureDevice.requestAccess(for: .video)
        default:
            problem = .cameraDenied
        }
    }

    private func setCover(_ photo: UIImage) async {
        isSaving = true
        defer { isSaving = false }
        do {
            try await BookCoverEditing.setCover(photo, on: book, store: coverStore, save: modelContext.save)
        } catch {
            problem = .saveFailed
        }
    }

    private func removeCover() async {
        do {
            try await BookCoverEditing.removeCover(from: book, store: coverStore, save: modelContext.save)
        } catch {
            problem = .saveFailed
        }
    }

    private enum Problem {
        case cameraUnavailable, cameraDenied, saveFailed

        var title: LocalizedStringKey {
            switch self {
            case .cameraUnavailable: "Камера недоступна"
            case .cameraDenied: "Нет доступа к камере"
            case .saveFailed: "Не удалось обновить обложку"
            }
        }

        var message: LocalizedStringKey {
            switch self {
            case .cameraUnavailable: "На этом устройстве нельзя сделать снимок."
            case .cameraDenied: "Разрешите доступ к камере в Настройках, чтобы сфотографировать обложку."
            case .saveFailed: "Попробуйте ещё раз."
            }
        }
    }
}
```

### `BookRow.swift` (строка списка и очистка лишних файлов при запуске)

Сам список должен быть `List` или `LazyVStack`, а не `VStack`: иначе все 500 строк создаются сразу.

```swift
import SwiftData
import SwiftUI

struct BookRow: View {
    let book: Book

    @ScaledMetric(relativeTo: .body) private var coverHeight: CGFloat = 60

    var body: some View {
        // Capped at 100 pt: the thumbnail is 300 px tall, sharp up to 100 pt at 3x.
        let height = min(coverHeight, 100)
        HStack(spacing: 12) {
            BookCoverView(coverID: book.coverID, variant: .thumbnail)
                .frame(width: height * 2 / 3, height: height)
            VStack(alignment: .leading, spacing: 2) {
                Text(book.title)
                    .font(.headline)
                Text(book.author)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }
        }
    }
}

extension View {
    /// Attach once to the root view, inside `.modelContainer`.
    func removesOrphanedCovers() -> some View {
        modifier(OrphanedCoverCleanup())
    }
}

private struct OrphanedCoverCleanup: ViewModifier {
    @Environment(\.modelContext) private var modelContext
    @Environment(\.coverStore) private var coverStore

    func body(content: Content) -> some View {
        content.task {
            // Deleting a photo cannot be undone, so skip the sweep when the library cannot be
            // read or looks empty: an empty context may be the wrong container or a fresh store.
            guard let bookCount = try? modelContext.fetchCount(FetchDescriptor<Book>()), bookCount > 0 else {
                return
            }
            var descriptor = FetchDescriptor<Book>(predicate: #Predicate { $0.coverID != nil })
            descriptor.propertiesToFetch = [\.coverID]
            guard let books = try? modelContext.fetch(descriptor) else { return }
            await coverStore.removeOrphans(referencedIDs: Set(books.compactMap(\.coverID)))
        }
    }
}
```

Подключение в корне приложения: `RootView().removesOrphanedCovers()` внутри `WindowGroup`, где уже стоит `.modelContainer(...)`.

### Info.plist

Ключ `NSCameraUsageDescription` (или настройка сборки `INFOPLIST_KEY_NSCameraUsageDescription`) со значением: «Камера нужна, чтобы сфотографировать обложку книги.» Без этого ключа приложение упадёт при открытии камеры.

