        #expect(pixelSize(of: thumbnail) == CGSize(width: 225, height: 300))
        // The red corner is top-left in the sensor's pixels; turned upright it is top-right.
        #expect(try isRed(full, x: 675, y: 300))
        #expect(try !isRed(full, x: 225, y: 300))
    }

    @Test func smallPhotoIsNotUpscaled() async throws {
        let store = CoverStore(directory: directory)
        let id = try await store.save(try makePhoto(width: 300, height: 400))

        let full = try #require(await CoverStore(directory: directory).image(for: id, variant: .full))
        #expect(pixelSize(of: full) == CGSize(width: 300, height: 400))
    }

    @Test func deletedCoverNoLongerLoads() async throws {
        let store = CoverStore(directory: directory)
        let id = try await store.save(try makePhoto(width: 300, height: 400))

        await store.delete(id)

        #expect(await store.image(for: id, variant: .full) == nil)
        #expect(await store.image(for: id, variant: .thumbnail) == nil)
        #expect(await CoverStore(directory: directory).image(for: id, variant: .full) == nil)
    }

    @Test func sweepRemovesOnlyUnreferencedCoversFromEarlierLaunches() async throws {
        let earlierLaunch = CoverStore(directory: directory)
        let kept = try await earlierLaunch.save(try makePhoto(width: 300, height: 400))
        let orphan = try await earlierLaunch.save(try makePhoto(width: 300, height: 400))

        let store = CoverStore(directory: directory)
        await store.removeOrphans(referencedIDs: [kept])

        #expect(await store.image(for: kept, variant: .full) != nil)
        #expect(await store.image(for: kept, variant: .thumbnail) != nil)
        #expect(await store.image(for: orphan, variant: .full) == nil)
        #expect(await store.image(for: orphan, variant: .thumbnail) == nil)
    }

    @Test func sweepKeepsAPhotoSavedThisLaunchBeforeTheBookIsSaved() async throws {
        let store = CoverStore(directory: directory)
        let justSaved = try await store.save(try makePhoto(width: 300, height: 400))

        await store.removeOrphans(referencedIDs: [])

        #expect(await CoverStore(directory: directory).image(for: justSaved, variant: .full) != nil)
    }
