/// Blue with a red top-left quadrant, so a test can tell which way the result is turned.
func makePhoto(width: Int, height: Int, orientation: UIImage.Orientation = .up) throws -> UIImage {
    let format = UIGraphicsImageRendererFormat()
    format.scale = 1
    let size = CGSize(width: width, height: height)
    let drawn = UIGraphicsImageRenderer(size: size, format: format).image { context in
        UIColor.blue.setFill()
        context.fill(CGRect(origin: .zero, size: size))
        UIColor.red.setFill()
        context.fill(CGRect(x: 0, y: 0, width: size.width / 2, height: size.height / 2))
    }
    return UIImage(cgImage: try #require(drawn.cgImage), scale: 1, orientation: orientation)
}

func pixelSize(of image: UIImage) -> CGSize {
    CGSize(width: image.size.width * image.scale, height: image.size.height * image.scale)
}

/// Whether the pixel at (x, y), counted from the top-left, is red (JPEG makes it approximate).
func isRed(_ image: UIImage, x: Int, y: Int) throws -> Bool {
    let cgImage = try #require(image.cgImage)
    var pixel = [UInt8](repeating: 0, count: 4)
    try pixel.withUnsafeMutableBytes { buffer in
        let context = try #require(CGContext(
            data: buffer.baseAddress, width: 1, height: 1, bitsPerComponent: 8, bytesPerRow: 4,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ))
        // CoreGraphics counts from the bottom-left: shift the image so (x, y) lands on the one pixel.
        context.draw(cgImage, in: CGRect(x: -x, y: y - cgImage.height + 1, width: cgImage.width, height: cgImage.height))
    }
    return pixel[0] > 200 && pixel[2] < 80
}
```

