```swift
import Foundation
import SwiftData

@Model
final class Book {
    var id: UUID
    var title: String
    var author: String
    var addedAt: Date

    /// Cover photo, at most 1200 px on the long side, JPEG. External storage lets
    /// SwiftData keep large blobs in files next to the store instead of in table rows.
    @Attribute(.externalStorage) private(set) var coverImageData: Data? = nil
    /// The same cover, at most 300 px on the long side, for the library list.
    @Attribute(.externalStorage) private(set) var coverThumbnailData: Data? = nil
    /// New value on every cover change; nil means the book has no cover.
    /// Views and the thumbnail cache key on it instead of comparing image bytes.
    private(set) var coverVersion: UUID? = nil

    init(id: UUID = UUID(), title: String, author: String, addedAt: Date = .now) {
        self.id = id
        self.title = title
        self.author = author
        self.addedAt = addedAt
    }

    var hasCover: Bool { coverVersion != nil }

    /// False once the book is deleted, including after the deletion is saved.
    var isStillStored: Bool { !isDeleted && modelContext != nil }

    func setCover(_ cover: CoverImages) {
        coverImageData = cover.full
        coverThumbnailData = cover.thumbnail
        coverVersion = UUID()
    }

    func removeCover() {
        coverImageData = nil
        coverThumbnailData = nil
        coverVersion = nil
    }
}

/// JPEG bytes of a processed cover in both sizes.
nonisolated struct CoverImages: Sendable {
    let full: Data
    let thumbnail: Data
}
