### CoverImageProcessor.swift

```swift
import UIKit

/// Turns a camera photo into the two JPEGs stored on `Book`.
nonisolated enum CoverImageProcessor {
    static let fullMaxPixelLength: CGFloat = 1200
    static let thumbnailMaxPixelLength: CGFloat = 300
    static let compressionQuality: CGFloat = 0.8

    enum Failure: Error {
        case emptyImage
        case encodingFailed
    }

    /// Runs off the main actor: redrawing a 12 MP photo takes long enough to drop frames.
    @concurrent
    static func makeCover(from photo: UIImage) async throws -> CoverImages {
        let full = try redraw(photo, maxPixelLength: fullMaxPixelLength)
        let thumbnail = try redraw(full, maxPixelLength: thumbnailMaxPixelLength)
        guard let fullData = full.jpegData(compressionQuality: compressionQuality),
              let thumbnailData = thumbnail.jpegData(compressionQuality: compressionQuality)
        else { throw Failure.encodingFailed }
        return CoverImages(full: fullData, thumbnail: thumbnailData)
    }

    /// Redraws the image upright (camera photos are stored sideways with a rotation tag),
    /// at most `maxPixelLength` on the long side and never larger than the original.
    /// The result carries no metadata, so the photo's location is not stored.
    static func redraw(_ image: UIImage, maxPixelLength: CGFloat) throws -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        guard pixelWidth >= 1, pixelHeight >= 1 else { throw Failure.emptyImage }
        let factor = min(1, maxPixelLength / max(pixelWidth, pixelHeight))
        let size = CGSize(
            width: max(1, (pixelWidth * factor).rounded()),
            height: max(1, (pixelHeight * factor).rounded())
        )
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: size, format: format).image { context in
            context.cgContext.interpolationQuality = .high
            image.draw(in: CGRect(origin: .zero, size: size))
        }
    }
}
