### CoverImageLoading.swift

```swift
import UIKit

nonisolated enum CoverImageDecoder {
    /// Decodes JPEG bytes off the main actor so scrolling never waits for it.
    @concurrent
    static func decode(_ data: Data) async -> UIImage? {
        guard let image = UIImage(data: data) else { return nil }
        return await image.byPreparingForDisplay() ?? image
    }
}

/// Decoded list thumbnails keyed by `Book.coverVersion`, so scrolling back up
/// does not decode again. NSCache also empties itself under memory pressure.
@MainActor
enum CoverThumbnailCache {
    private static let storage: NSCache<NSUUID, UIImage> = {
        let cache = NSCache<NSUUID, UIImage>()
        cache.totalCostLimit = 40 * 1024 * 1024 // about 150 thumbnails
        return cache
    }()

    static func image(for version: UUID) -> UIImage? {
        storage.object(forKey: version as NSUUID)
    }

    static func insert(_ image: UIImage, for version: UUID) {
        let pixels = image.size.width * image.scale * image.size.height * image.scale
        storage.setObject(image, forKey: version as NSUUID, cost: Int(pixels) * 4)
    }
}
