### BookCoverImage.swift

```swift
import SwiftUI

/// A book's cover, or a placeholder when it has none.
struct BookCoverImage: View {
    enum Style {
        case thumbnail
        case large
    }

    let book: Book
    let style: Style

    @Environment(\.displayScale) private var displayScale
    @ScaledMetric(relativeTo: .body) private var thumbnailWidth: CGFloat = 40
    @State private var loaded: LoadedCover?

    var body: some View {
        let version = book.coverVersion
        content(image: displayedImage(for: version))
            .task(id: version) { await load(version) }
    }

    @ViewBuilder
    private func content(image: UIImage?) -> some View {
        switch style {
        case .thumbnail:
            // Never wider than the stored thumbnail can fill sharply in a 2:3 frame.
            let maxWidth = CoverImageProcessor.thumbnailMaxPixelLength / 1.5 / displayScale
            let width = min(thumbnailWidth, maxWidth)
            Group {
                if let image {
                    Image(uiImage: image).resizable().scaledToFill()
                } else {
                    placeholder
                }
            }
            .frame(width: width, height: width * 1.5)
            .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
        case .large:
            Group {
                if let image {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFit()
                        .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
                } else {
                    placeholder.aspectRatio(2.0 / 3.0, contentMode: .fit)
                }
            }
            .frame(maxWidth: 220, maxHeight: 330)
        }
    }

    private var placeholder: some View {
        RoundedRectangle(cornerRadius: cornerRadius)
            .fill(.quaternary)
            .overlay {
                Image(systemName: "book.closed")
                    .font(style == .thumbnail ? .body : .largeTitle)
                    .foregroundStyle(.secondary)
            }
    }

    private var cornerRadius: CGFloat { style == .thumbnail ? 4 : 8 }

    private func displayedImage(for version: UUID?) -> UIImage? {
        guard let version else { return nil }
        if let loaded, loaded.version == version { return loaded.image }
        if style == .thumbnail, let cached = CoverThumbnailCache.image(for: version) { return cached }
        // After a retake, keep showing the previous photo until the new one is decoded.
        return loaded?.image
    }

    private func load(_ version: UUID?) async {
        guard let version else {
            // Forget a removed cover so it cannot reappear while a later one decodes.
            loaded = nil
            return
        }
        guard loaded?.version != version else { return }
        if style == .thumbnail, let cached = CoverThumbnailCache.image(for: version) {
            loaded = LoadedCover(version: version, image: cached)
            return
        }
        let data = style == .thumbnail ? book.coverThumbnailData : book.coverImageData
        guard let data, let image = await CoverImageDecoder.decode(data) else { return }
        if style == .thumbnail { CoverThumbnailCache.insert(image, for: version) }
        // A newer cover may have replaced this one while it was decoding.
        guard !Task.isCancelled else { return }
        loaded = LoadedCover(version: version, image: image)
    }
}

private struct LoadedCover {
    let version: UUID
    let image: UIImage
}
