import SwiftUI

/// The large cover at the top of the book screen, with buttons to photograph,
/// retake, or remove it.
struct BookCoverHeader: View {
    let book: Book

    @Environment(\.openURL) private var openURL
    @State private var isCameraPresented = false
    @State private var isSaving = false
    @State private var isCameraDeniedAlertPresented = false
    @State private var isProcessingFailedAlertPresented = false
    @State private var isRemoveConfirmationPresented = false

    private static let logger = Logger(subsystem: "Slumpy", category: "BookCover")

    var body: some View {
        VStack(spacing: 12) {
            BookCoverImage(book: book, style: .large)
                .overlay {
                    if isSaving { ProgressView() }
                }
                .accessibilityElement(children: .ignore)
                .accessibilityLabel(book.hasCover ? "Обложка" : "Нет обложки")
                .accessibilityValue(isSaving ? "Сохранение" : "")
                .accessibilityAddTraits(.isImage)
            controls
                .disabled(isSaving)
        }
        .frame(maxWidth: .infinity)
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker(
                onCapture: { photo in
                    isCameraPresented = false
                    save(photo)
                },
                onCancel: { isCameraPresented = false }
            )
            .ignoresSafeArea()
        }
        .alert("Нет доступа к камере", isPresented: $isCameraDeniedAlertPresented) {
            Button("Открыть Настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Чтобы сфотографировать обложку, разрешите Slumpy доступ к камере в Настройках.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $isProcessingFailedAlertPresented) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте сфотографировать ещё раз.")
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isRemoveConfirmationPresented, titleVisibility: .visible) {
            Button("Удалить обложку", role: .destructive) {
                book.removeCover()
                persist()
            }
        }
    }

    @ViewBuilder
    private var controls: some View {
        let canUseCamera = UIImagePickerController.isSourceTypeAvailable(.camera)
        if book.hasCover {
            Menu("Обложка") {
                if canUseCamera {
                    Button("Переснять", systemImage: "camera") { openCamera() }
                }
                Button("Удалить", systemImage: "trash", role: .destructive) {
                    isRemoveConfirmationPresented = true
                }
            }
        } else if canUseCamera {
            Button("Сфотографировать обложку", systemImage: "camera") { openCamera() }
        }
    }

    private func openCamera() {
        Task {
            switch AVCaptureDevice.authorizationStatus(for: .video) {
            case .authorized:
                isCameraPresented = true
            case .notDetermined:
                isCameraPresented = await AVCaptureDevice.requestAccess(for: .video)
            default:
                isCameraDeniedAlertPresented = true
            }
        }
    }

    private func save(_ photo: UIImage) {
        isSaving = true
        Task {
            defer { isSaving = false }
            let cover: CoverImages
            do {
                cover = try await CoverImageProcessor.makeCover(from: photo)
            } catch {
                isProcessingFailedAlertPresented = true
                return
            }
            // The book may have been deleted while the photo was being processed.
            guard book.isStillStored else { return }
            book.setCover(cover)
            persist()
        }
    }

    /// Saves right away so a fresh cover is on disk even if the app is closed next.
    /// On failure the change stays in the context and autosave retries it.
    private func persist() {
        do {
            try book.modelContext?.save()
        } catch {
            Self.logger.error("Saving the book cover failed: \(String(describing: error))")
        }
    }
}
