    /// only tagged as rotated does not pass for an upright one.
    private func uprightPixelSize(of jpeg: Data) throws -> CGSize {
        let image = try #require(UIImage(data: jpeg))
        #expect(image.imageOrientation == .up)
        let pixels = try #require(image.cgImage)
        return CGSize(width: pixels.width, height: pixels.height)
    }

    private func makePixels(width: Int, height: Int) throws -> CGImage {
        let context = try #require(CGContext(
            data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue
        ))
        context.setFillColor(red: 0.2, green: 0.4, blue: 0.6, alpha: 1)
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        return try #require(context.makeImage())
    }
