## Что проверить на iPhone

Камера работает только на настоящем телефоне, в симуляторе её нет.

1. Сфотографируйте обложку, держа телефон вертикально. Обложка должна быть не повёрнута ни на экране книги, ни в списке.
2. Откажите в доступе к камере, потом снова нажмите кнопку. Должно появиться сообщение, а «Открыть Настройки» — открыть настройки приложения.
3. Переснимите обложку: новая заменяет старую. Удалите обложку: вернётся заглушка. Сфотографируйте снова: старая обложка не должна мелькнуть.
4. Закройте приложение полностью и откройте снова: обложки на месте.
5. Обновите приложение поверх старой версии с книгами: все книги на месте, у них заглушки.
6. В библиотеке на 500+ книг быстро прокрутите список вверх и вниз: он не должен дёргаться.
7. Проверьте экран книги и список в светлой и тёмной теме, с самым крупным шрифтом, на iOS 18 и на текущей iOS.

Ниже готовый код в четырёх файлах. Скомпилировать и запустить тесты здесь было нельзя: для этого нужен Mac с Xcode. Поэтому код пока не проверен, первым делом его нужно собрать и прогнать тесты на Mac.

## Как это работает для пользователя

На экране истории появляется кнопка «Экспорт в CSV». Она открывает стандартное меню «Поделиться»: можно сохранить в «Файлы», отправить письмом или в мессенджер. Получается файл `История чтения Slumpy 2026-10-27.csv`, который открывается в Excel и Numbers уже разложенным по колонкам, с русскими буквами без искажений.

## Код

### 1. `ReadingHistoryCSV.swift`: сборка CSV (только Foundation)

```swift
import Foundation

/// A plain value snapshot of one reading session. The export builds the file off the main actor,
/// so it must not touch `ReadingSession` directly (it may be a non-Sendable model object).
nonisolated struct ReadingHistoryRow: Sendable, Equatable {
    var startedAt: Date
    var duration: TimeInterval
    var timeZoneIdentifier: String
    var bookTitle: String
    var bookAuthor: String
}

/// Builds a reading-history CSV that Excel and Numbers open directly.
nonisolated enum ReadingHistoryCSV {
    enum Delimiter: String, Sendable {
        case comma = ","
        case semicolon = ";"

        /// Excel splits columns by the system list separator: `;` in regions where the decimal
        /// separator is a comma (Russia, most of Europe), `,` elsewhere. Numbers accepts both.
        static func matching(_ locale: Locale) -> Delimiter {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    static let header = ["Начало", "Длительность, мин", "Книга", "Автор"]

    /// File bytes: UTF-8 with a BOM, without which Excel reads Cyrillic as mojibake.
    static func data(
        for rows: [ReadingHistoryRow],
        delimiter: Delimiter,
        fallbackTimeZone: TimeZone = .current
    ) -> Data {
        let byteOrderMark = Data([0xEF, 0xBB, 0xBF])
        return byteOrderMark + Data(text(for: rows, delimiter: delimiter, fallbackTimeZone: fallbackTimeZone).utf8)
    }

    /// CSV text per RFC 4180: CRLF line endings, rows in chronological order.
    static func text(
        for rows: [ReadingHistoryRow],
        delimiter: Delimiter,
        fallbackTimeZone: TimeZone = .current
    ) -> String {
        var lines = [line(header.map { escaped($0, delimiter: delimiter) }, delimiter: delimiter)]
        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            lines.append(line([
                startText(row, fallbackTimeZone: fallbackTimeZone),
                String(minutes(row.duration)),
                escaped(neutralizingFormula(row.bookTitle), delimiter: delimiter),
                escaped(neutralizingFormula(row.bookAuthor), delimiter: delimiter),
            ], delimiter: delimiter))
        }
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    /// Wall-clock start time where the session happened, as `yyyy-MM-dd HH:mm`, which both
    /// Excel and Numbers recognize as a date and time in any region.
    static func startText(_ row: ReadingHistoryRow, fallbackTimeZone: TimeZone) -> String {
        var calendar = Calendar(identifier: .gregorian)
        // An identifier the system no longer knows (renamed zone, damaged record) must not
        // break the export; the device time zone is the closest guess.
        calendar.timeZone = TimeZone(identifier: row.timeZoneIdentifier) ?? fallbackTimeZone
        let parts = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: row.startedAt)
        return String(
            format: "%04ld-%02ld-%02ld %02ld:%02ld",
            parts.year ?? 0, parts.month ?? 0, parts.day ?? 0, parts.hour ?? 0, parts.minute ?? 0
        )
    }

    /// Whole minutes, rounded to nearest. A whole number avoids the decimal-separator clash
    /// (`12.5` reads as text or a date in regions that use a decimal comma).
    static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((duration / 60).rounded())
    }

    /// A cell starting with `=`, `+`, `-`, `@`, tab, or CR is run as a formula by spreadsheets
    /// (CSV injection). A leading apostrophe keeps it plain text.
    static func neutralizingFormula(_ value: String) -> String {
        guard let first = value.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) else {
            return value
        }
        return "'" + value
    }

    /// Quotes a field that contains the delimiter, a quote, or a line break; doubles inner quotes.
    static func escaped(_ value: String, delimiter: Delimiter) -> String {
        let needsQuoting = value.contains("\"")
            || value.contains(delimiter.rawValue)
            || value.contains(where: \.isNewline)
        guard needsQuoting else { return value }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    private static func line(_ fields: [String], delimiter: Delimiter) -> String {
        fields.joined(separator: delimiter.rawValue)
    }
}
```

