### 1. Экспорт: `ReadingHistoryExport.swift`

```swift
import CoreTransferable
import Foundation
import UniformTypeIdentifiers

/// A snapshot of reading sessions that ShareLink turns into a CSV file
/// only when the user picks a destination in the share sheet.
nonisolated struct ReadingHistoryExport: Transferable, Sendable {
    struct Row: Sendable, Equatable {
        var startedAt: Date
        var duration: TimeInterval
        var timeZone: TimeZone
        var title: String
        var author: String
    }

    let rows: [Row]
    let delimiter: Character
    let exportedAt: Date

    init(sessions: [ReadingSession], locale: Locale = .current, now: Date = .now) {
        self.init(
            rows: sessions.map { session in
                Row(
                    startedAt: session.startedAt,
                    duration: session.duration,
                    // An unknown identifier (e.g. from corrupted data) falls back to the
                    // phone's current zone instead of dropping the session.
                    timeZone: TimeZone(identifier: session.timeZoneIdentifier) ?? .current,
                    title: session.bookTitle,
                    author: session.bookAuthor
                )
            },
            delimiter: Self.delimiter(for: locale),
            exportedAt: now
        )
    }

    init(rows: [Row], delimiter: Character, exportedAt: Date) {
        self.rows = rows.sorted { $0.startedAt < $1.startedAt }
        self.delimiter = delimiter
        self.exportedAt = exportedAt
    }

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            // A fresh folder per export, so the file keeps its readable name without collisions.
            let folder = URL.temporaryDirectory.appending(path: UUID().uuidString, directoryHint: .isDirectory)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            let file = folder.appending(path: export.fileName, directoryHint: .notDirectory)
            try export.csvData().write(to: file, options: .atomic)
            return SentTransferredFile(file)
        }
    }

    var fileName: String {
        let day = Self.localDateTime(exportedAt, in: .current).prefix(10)
        return String(localized: "История чтения \(String(day)).csv")
    }

    /// UTF-8 with BOM: without the BOM Excel reads Cyrillic as mojibake.
    func csvData() -> Data {
        Data([0xEF, 0xBB, 0xBF]) + Data(csvText().utf8)
    }

    func csvText() -> String {
        let separator = String(delimiter)
        let header = [
            String(localized: "Начало"),
            String(localized: "Длительность, мин"),
            String(localized: "Книга"),
            String(localized: "Автор"),
        ].map(Self.textField)
        var lines = [header.joined(separator: separator)]
        for row in rows {
            lines.append([
                Self.localDateTime(row.startedAt, in: row.timeZone),
                String(Self.wholeMinutes(row.duration)),
                Self.textField(row.title),
                Self.textField(row.author),
            ].joined(separator: separator))
        }
        // RFC 4180 line endings; Excel and Numbers both accept them.
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    /// Excel splits columns by the system list separator: ";" where the decimal
    /// separator is "," (Russia, most of Europe), "," elsewhere. Numbers detects either.
    static func delimiter(for locale: Locale) -> Character {
        locale.decimalSeparator == "," ? ";" : ","
    }

    /// "yyyy-MM-dd HH:mm" in the zone where the session happened.
    /// Excel and Numbers recognize this form as a date and time in any locale.
    static func localDateTime(_ date: Date, in timeZone: TimeZone) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = timeZone
        let c = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return String(
            format: "%04d-%02d-%02d %02d:%02d",
            c.year ?? 0, c.month ?? 0, c.day ?? 0, c.hour ?? 0, c.minute ?? 0
        )
    }

    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        // The cap keeps a corrupted huge value from trapping in the Int conversion.
        return Int((min(duration, 1_000_000_000) / 60).rounded())
    }

    /// Always quoted, inner quotes doubled (RFC 4180), so commas, semicolons,
    /// quotes and line breaks inside titles stay in one cell.
    /// A leading = + - @ would make Excel run the text as a formula; an apostrophe prevents that.
    static func textField(_ value: String) -> String {
        let formulaStarts: Set<Character> = ["=", "+", "-", "@", "\t", "\r"]
        var text = value
        if let first = text.first, formulaStarts.contains(first) {
            text = "'" + text
        }
        return "\"" + text.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }
}
```

