    typealias Loader = @Sendable (BookID) async throws -> UIImage

    private let loader: Loader
    private let images = NSCache<NSString, UIImage>()
    /// Loads in progress: a second request for the same id awaits the same task.
    private var inFlight: [BookID: Task<UIImage, any Error>] = [:]

    init(
        memoryLimitBytes: Int = 50 * 1024 * 1024,
        loader: @escaping Loader = { try await loadCoverFromDisk(id: $0) }
    ) {
        self.loader = loader
        images.totalCostLimit = memoryLimitBytes
    }

    func cachedCover(for id: BookID) -> UIImage? {
        images.object(forKey: id as NSString)
    }

    /// Returns the cover, reading the disk at most once per id at a time.
    /// A cancelled caller keeps waiting and still gets the image, so the shared load is never
    /// cancelled by a screen that went away; callers check `Task.isCancelled` before using it.
    func cover(for id: BookID) async throws -> UIImage {
        if let image = cachedCover(for: id) { return image }
        if let task = inFlight[id] { return try await task.value }

        // No suspension point between the check above and the insert below, so on the main
        // actor no other request can start a second load for this id.
        let loader = self.loader
        let task = Task.detached(priority: Task.currentPriority) {
            let image = try await loader(id)
            // Decode here, off the main thread, instead of on first draw while scrolling.
            return image.preparingForDisplay() ?? image
        }
        inFlight[id] = task

        do {
            let image = try await task.value
            images.setObject(image, forKey: id as NSString, cost: Self.cost(of: image))
            inFlight[id] = nil
            return image
        } catch {
            // Failures are not remembered: the next request tries the disk again.
            inFlight[id] = nil
            throw error
        }
    }

    private static func cost(of image: UIImage) -> Int {
        if let cgImage = image.cgImage { return cgImage.bytesPerRow * cgImage.height }
        let pixels = image.size.width * image.scale * image.size.height * image.scale
        return Int(pixels) * 4
    }
}
```

### 2. Изменение в существующей функции

Перед уже существующей `loadCoverFromDisk` нужно дописать одно слово `@concurrent`. Тело функции не меняется:

```swift
@concurrent
func loadCoverFromDisk(id: BookID) async throws -> UIImage {
    // existing body unchanged
}
```

### 3. Обложка на экране (`BookCoverView.swift`)

```swift
import SwiftUI

struct BookCoverView: View {
    let bookID: BookID

    var body: some View {
        // New identity per book: state from the previous book is discarded.
        CoverImage(bookID: bookID).id(bookID)
    }
}

private struct CoverImage: View {
    let bookID: BookID
    @State private var image: UIImage?

    init(bookID: BookID) {
        self.bookID = bookID
        _image = State(initialValue: CoverCache.shared.cachedCover(for: bookID))
    }

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image).resizable().scaledToFit()
            } else {
                Rectangle().fill(.quaternary)
            }
        }
        .task {
            guard image == nil else { return }
            let loaded = try? await CoverCache.shared.cover(for: bookID)
            guard !Task.isCancelled else { return }
            image = loaded
        }
    }
}
```

### 4. Тесты (`CoverCacheTests.swift`)

```swift
import Testing
import UIKit
@testable import Slumpy

@MainActor
struct CoverCacheTests {
    @Test func simultaneousRequestsReadDiskOnce() async throws {
        let reads = ReadCounter()
        let cache = CoverCache { _ in
            await reads.increment()
            try await Task.sleep(for: .milliseconds(200))
            return UIImage()
        }
        async let first = cache.cover(for: "book-1")
        async let second = cache.cover(for: "book-1")
        let (a, b) = try await (first, second)
        #expect(a === b)
        #expect(await reads.count == 1)
    }

    @Test func loadedCoverIsServedFromMemory() async throws {
        let reads = ReadCounter()
        let cache = CoverCache { _ in
            await reads.increment()
            return UIImage()
        }
        _ = try await cache.cover(for: "book-1")
        _ = try await cache.cover(for: "book-1")
        #expect(cache.cachedCover(for: "book-1") != nil)
        #expect(await reads.count == 1)
    }

    @Test func failedLoadIsRetried() async throws {
        let reads = ReadCounter()
        let cache = CoverCache { _ in
            if await reads.increment() == 1 { throw CocoaError(.fileReadNoSuchFile) }
            return UIImage()
        }
        await #expect(throws: CocoaError.self) { try await cache.cover(for: "book-1") }
        _ = try await cache.cover(for: "book-1")
        #expect(await reads.count == 2)
    }

    @Test func leavingScreenDoesNotCancelSharedLoad() async throws {
        let reads = ReadCounter()
        let cache = CoverCache { _ in
            await reads.increment()
            try await Task.sleep(for: .milliseconds(200))
            return UIImage()
        }
        let firstScreen = Task { try await cache.cover(for: "book-1") }
        await Task.yield()
        firstScreen.cancel()
        _ = try await cache.cover(for: "book-1")
        #expect(cache.cachedCover(for: "book-1") != nil)
        #expect(await reads.count == 1)
    }
}

private actor ReadCounter {
    private(set) var count = 0
    @discardableResult func increment() -> Int { count += 1; return count }
}
```

## Ключевые решения

- **Одна загрузка на обложку.** Кеш помнит не только готовые обложки, но и те, что сейчас грузятся. Если второй экран просит обложку во время загрузки, он ждёт ту же загрузку, а не запускает новую. Проверка «грузится ли уже» и запись «начинаю грузить» идут одним шагом, без пауз между ними, поэтому два экрана не могут проскочить одновременно. Это проверяет первый тест.
- **Кеш работает в главном потоке, а чтение с диска — нет.** Экран сразу, без ожидания, узнаёт, есть ли обложка в памяти. Поэтому при прокрутке нет мигания заглушки. Чтение с диска и подготовка картинки к показу идут в фоне, чтобы прокрутка не дёргалась.
- **Ушедший экран не отменяет загрузку.** Если пользователь пролистал дальше, обложка всё равно догрузится и останется в памяти для других экранов. Экран, который уже исчез, её не покажет.
- **Ошибки не запоминаются.** Если чтение не удалось, следующий запрос попробует снова. Пока обложки нет, видна серая заглушка.
- **Память ограничена.** Кеш занимает до 50 МБ. Сверх этого и при нехватке памяти у телефона система сама выбрасывает старые обложки.
- **Быстрое переключение книг.** Если на одном месте экрана книга быстро сменилась на другую, старая обложка не подменит новую. Об этой ошибке ревьюер и предупредил.

## Допущения

- Идентификатор книги — строка (`String`). Если это другой тип, нужно поменять одну строку `typealias BookID`.
- `loadCoverFromDisk` — обычная функция, не метод другого объекта. Без слова `@concurrent` при некоторых настройках проекта чтение с диска уйдёт в главный поток, и прокрутка начнёт тормозить.
- «Не грузить дважды» я понял как «никогда не читать одну обложку с диска одновременно дважды». Если система выбросила обложку из памяти или чтение не удалось, её прочитают снова, и это задумано.
- В тестах модуль приложения назван `Slumpy`.

